set-variable.value:
@{
      if (context.Request.Method != "POST" || context.Request.Body == null) { return ""; }
      var body = context.Request.Body.As<JObject>(preserveContent: true);
      return (string)body["method"] ?? "";
    }

@{
          var body = context.Request.Body.As<JObject>(preserveContent: true);
          return body["id"] == null ? "null" : body["id"].ToString(Newtonsoft.Json.Formatting.None);
        }

return-response.set-body:
@{
            var retry = context.Variables.ContainsKey("mcpRetryAfter") ? ((int)context.Variables["mcpRetryAfter"]).ToString() : context.Response.Headers.GetValueOrDefault("Retry-After", "{{opsdesk-ratelimit-period}}");
            var id = JToken.Parse((string)context.Variables.GetValueOrDefault("mcpRequestId", "null"));
            return new JObject(
              new JProperty("jsonrpc", "2.0"), new JProperty("id", id),
              new JProperty("result", new JObject(
                new JProperty("isError", true),
                new JProperty("content", new JArray(new JObject(
                  new JProperty("type", "text"),
                  new JProperty("text", "Rate limit exceeded: {{opsdesk-ratelimit-calls}} tool calls per minute for this agent. Retry after " + retry + " s."))))))).ToString();
          }
